actionConfiguration.body:
select *
from public.save_venue_master(
  nullif(
    {{ Number(appsmith.store.current_venue_id || 0) }}::bigint,
    0
  ),

  {{ appsmith.store.current_client_id }}::uuid,

  {{ (inpVenueName.text ?? "").trim() }}::text,
  {{ (inpVenueAddress.text ?? "").trim() }}::text,
  {{ (inpVenuePhone.text ?? "").trim() }}::text,
  {{ (inpVenueMobile.text ?? "").trim() }}::text,
  {{ (inpVenueEmail.text ?? "").trim() }}::text,
  {{ (inpVenueNotes.text ?? "").trim() }}::text,

  {{ chkVenueActive.isChecked }}::boolean,

  {{
    (msVenueContacts.selectedOptionValues || []).length
      ? `{${msVenueContacts.selectedOptionValues.map(Number).join(",")}}`
      : "{}"
  }}::bigint[]
);
